def report8():
    rows=read('lab8_final_scenarios.csv');py=read('lab8_python_scenarios.csv');base=rows[0];b=py[0];v=js('verification.json');cert=js('lab8_certificates.json')
    story=title(8,'Нелинейная производственная программа и 20 сценариев')
    story += [heading('1. Условия модели'),p('Методичка: стр. 38-40 и 43. В этой работе дополнительный продукт варианта 11 - йогурт. Выпуск qⱼ измеряется в т/сут, базовые цены p⁰ⱼ - в ₽/т, расход a⁰ⱼ - в т сырья/т продукта. База q⁰ = 100 т/сут.'),table(['Продукт','p⁰','a⁰','e цены','e расхода','Минимум, т'],[['Молоко','24 000','1,01','-0,062','-0,014','25'],['Кефир','27 000','1,01','-0,062','-0,012','30'],['Сметана','138 000','9,45','-0,022','-0,015','1,5'],['Йогурт','25 000','0,85','-0,047','-0,017','0,75']],[100,85,65,85,85,W-420]),p('Минимум каждого выпуска соответствует половине часа работы оборудования. Сырьё: 1 400 т/сут. Общая линия молока и кефира: 50 и 60 т/ч, до 21 ч. Общая линия сметаны и йогурта: 3 и 1,5 т/ч, до 18 ч.'),heading('2. Математическая модель'),formula([r'p_j(q_j)=p_j^0(q_j/100)^{e_j^p},\quad a_j(q_j)=a_j^0(q_j/100)^{e_j^a}',r'\max R=\sum_jp_j^0\,100(q_j/100)^{1+e_j^p}',r'\sum_ja_j^0\,100(q_j/100)^{1+e_j^a}\leq1400',r'q_M/50+q_K/60\leq21,\quad q_S/3+q_Y/1.5\leq18',r'q_M\geq25,\quad q_K\geq30,\quad q_S\geq1.5,\quad q_Y\geq0.75'],12.5),p('Общий расход и выручка содержат степень 1 + эластичность, поскольку удельный показатель умножается на выпуск. В GAMS выручка делится на 10⁶ для численной устойчивости; в результатах она возвращена в рубли.','SmallRU'),PageBreak(),heading('3. Базовый оптимальный план'),table(['Продукт','Выпуск, т/сут','Цена, ₽/т','Удельный расход, т/т'],[[name,number(base['q_'+prod],6),number(b['price_'+prod],2),number(b['input_'+prod],6)] for name,prod in zip(['Молоко','Кефир','Сметана','Йогурт'],['milk','kefir','cream','yogurt'])],[110,135,125,W-370]),p(f'<b>Выручка: {number(base["objective_rub"],2)} ₽/сут.</b>'),table(['Ресурс','Использование','Лимит','Предельная цена'],[['Сырьё, т',number(base['raw_used'],6),'1 400',number(base['shadow_raw'],2)+' ₽/т'],['Линия молоко/кефир, ч',number(base['mk_used'],6),'21',number(base['shadow_mk'],2)+' ₽/ч'],['Линия сметана/йогурт, ч',number(base['cy_used'],6),'18',number(base['shadow_cy'],2)+' ₽/ч']],[160,110,65,W-335]),p('В базовом плане все три общих ограничения активны. Кефир составляет основную часть выпуска, но молоко также производится: падающая цена дополнительного кефира меняет сравнение предельных доходов. Сметана и йогурт делят линию; их выпуск определяется одновременно выручкой, расходом сырья и временем фасовки.'),p('Предельные цены показывают локальное увеличение максимальной выручки от ещё одной тонны сырья или часа линии. Это производные в базовом оптимуме, а не тарифы на закупку. При изменении условий на 10-20% нужно заново решать модель.'),heading('4. Как пользователь задаёт сценарии'),p('Открыть data/scenarios.csv в Excel или текстовом редакторе. Каждая строка задаёт raw_t, mk_hours, cy_hours и четыре p_... при базовом выпуске 100 т/сут. Уникальный scenario_id сохраняется в результате. Затем запустить run_all.ps1 или обновить GAMS-включение скриптом prepare_data.py и запустить lab8.gms. Проверяются положительность, уникальность и допустимость минимального выпуска.','SmallRU'),p('Изменяется базовая цена, а не готовая цена в оптимуме: фактическая цена автоматически рассчитывается по степенной функции. Постоянные коэффициенты a⁰, e и производительности оборудования явно записаны в модели и итоговой текстовой таблице.','SmallRU'),PageBreak(),heading('5. Входные условия 20 сценариев'),p('Значения p - ₽/т при 100 т/сут. В идентификаторах 80/90/110/120 означают процент от базового значения. combined: сырьё +10%, время первой линии -10%, второй +10%. Остальные коэффициенты неизменны.','SmallRU'),table(['Сценарий','Сырьё, т','МК, ч','СЙ, ч','p мол.','p кеф.','p смет.','p йог.'],[[r['scenario_id'],number(r['raw_t'],0),number(r['mk_hours'],1),number(r['cy_hours'],1)]+[number(r['p_'+prod],0) for prod in ['milk','kefir','cream','yogurt']] for r in rows],[122,51,43,43,60,60,65,W-444],True),Spacer(1,12),p('20 строк представляют разные условия. Три начальные точки каждого сценария используются для проверки сходимости и не подменяют сценарии. Цена каждого продукта исследована отдельно при -10% и +10%; сырьё - при -20%, -10%, +10%, +20%; доступное время линий - при -20%, -10%, +10%.','SmallRU'),PageBreak(),heading('6. Результаты сценариев'),p('q - т/сут; R - млн ₽/сут. Статус GAMS для всех исходных и преобразованных NLP: modelstat=2 (Locally Optimal), solvestat=1 (Normal Completion). Звёздочка в последнем столбце означает дополнительную глобальную численную проверку, описанную далее.','SmallRU'),table(['Сценарий','q мол.','q кеф.','q смет.','q йог.','R, млн ₽','Статус'],[[r['scenario_id']]+[number(r['q_'+prod],3) for prod in ['milk','kefir','cream','yogurt']]+[number(float(r['objective_rub'])/1e6,6),'2/1 *'] for r in rows],[122,60,70,60,60,85,W-457],True),Spacer(1,10),p('Полная машинная таблица: results/lab8_scenarios_table.txt (UTF-8, разделитель табуляция). Каждая строка содержит условия, четыре переменные, цель, статусы, расход ресурсов, множители и контрольные разрывы. CSV-копия: lab8_final_scenarios.csv. Все 60 исходных запусков сохранены в lab8_gams_starts.csv.','SmallRU'),PageBreak(),heading('7. Почему глобальность можно проверить'),p('В исходных переменных общий расход сырья вогнут; его ограничение сверху само по себе не задаёт выпуклую область. Поэтому статус локального решателя не превращается автоматически в доказательство глобальности. Для этого варианта существует монотонная замена:'),formula([r't_j=a_j^0(q_j/100)^{b_j},\quad b_j=1+e_j^a\in(0,1)',r'q_j=100(t_j/a_j^0)^{1/b_j},\quad \sum_j100t_j\leq B',r'R(t)=\sum_j100p_j^0(t_j/a_j^0)^{s_j},\quad s_j=(1+e_j^p)/b_j']),p('Показатели выручки sⱼ: '+', '.join(number(x,6) for x in cert['objective_powers'])+'. Все находятся между 0 и 1, поэтому выручка вогнута. Времена линий состоят из выпуклых функций с показателями 1/bⱼ &gt; 1. Баланс сырья линейный, нижние и верхние границы образуют прямоугольник. Получается выпуклая задача максимизации вогнутой функции.'),p('Численная проверка строит верхнюю оценку на всей допустимой области. Для ограничений g(t) ≤ 0 и неотрицательных множителей λ функция L = F - λᵀg вогнута. Её касательная сверху ограничивает L, а на допустимых точках F ≤ L. Максимум касательной на ограничивающем прямоугольнике вычисляется покомпонентно:'),formula([r'd=\nabla F(t^*)-J_g(t^*)^T\lambda',r'U=F(t^*)-\lambda^Tg(t^*)+\sum_j\max\{d_j(l_j-t_j^*),d_j(u_j-t_j^*)\}'],11.7),p('F здесь измеряется в млн ₽. К оценке добавлен численный запас 10⁻⁸ относительного масштаба. Это проверка с допусками арифметики с плавающей точкой, а не интервальное доказательство с точными числами. Приёмочный разрыв верхней оценки и найденной выручки задан ≤10⁻⁶; фактически для всех сценариев он меньше 1,2·10⁻⁸.'),heading('8. Контроль вычислений'),p(f'GAMS/CONOPT 4: 20 × 3 = 60 запусков исходной модели и 20 преобразованной. Python/SLSQP: ещё 60 запусков преобразованной задачи с аналитическими градиентами. Максимальное относительное расхождение GAMS и Python: {v["lab8_max_objective_relative_difference"]:.3e}; максимальная разница выпуска: {v["lab8_max_q_absolute_difference_t"]:.6f} т. Все ограничения пересчитаны из исходных данных. Разброс выручки трёх стартов существенно меньше требуемых 0,1%.','SmallRU'),PageBreak(),heading('9. Сценарная выручка и воспроизведение')]
    plt.rcParams['font.family']='Arial'
    fig,ax=plt.subplots(figsize=(8,5));ax.barh([r['scenario_id'] for r in rows],[float(r['objective_rub'])/1e6 for r in rows],color='#216e94');ax.invert_yaxis();ax.set_xlabel('Выручка, млн ₽/сут');ax.axvline(float(base['objective_rub'])/1e6,color='#c86636',lw=1.2,ls='--');ax.grid(axis='x',alpha=.2);ax.set_axisbelow(True);fig.tight_layout();path=TEMP/'scenario_revenue.png';fig.savefig(path,dpi=145);plt.close(fig)
    story += [Image(str(path),width=W,height=W*5/8),p('Пунктир - базовая выручка. Изменения показаны при повторном решении всех ограничений, поэтому эффект может быть нелинейным.','SmallRU'),p('Основные уравнения исходной GAMS-модели:','SmallRU')]+code("obj.. z =e= sum(j,p0(j)*100*rPower(q(j)/100,1+ep(j)))/1e6;\nraw.. sum(j,a0(j)*100*rPower(q(j)/100,1+ea(j))) =l= available;\nmk.. q('milk')/50+q('kefir')/60 =l= tm;\ncy.. q('cream')/3+q('yogurt')/1.5 =l= ts;")
    story += [Spacer(1,10),p('Полный исходник: models/lab8.gms; условия: data/scenarios.csv и models/scenarios.inc; независимый контроль: scripts/independent_check.py; сверка: scripts/verify_gams.py; протокол: logs/lab8.lst. Факультативная часть: цены, удельные расходы, предельные цены и чтение экспорта в Python выполнены.','SmallRU'),ref('Карточка №8 и сценарное дополнение преподавателя','https://sdo.timacad.ru/mod/assign/view.php?id=26169'),ref('GAMS: экспорт текстовых таблиц через Put','https://www.gams.com/latest/docs/UG_Put.html'),ref('GAMS Forum: сохранять результаты каждого сценария внутри цикла','https://forum.gams.com/t/export-looped-tables-to-excel/1681')]
    return build('lab8_variant11_report.pdf',story)

def report10():
    rows=read('lab10_python_dea.csv');g=read('lab10_gams_dea.csv');stats=js('lab10_stats.json');v=js('verification.json')
    story=title(10,'DEA и две проверки корреляции Спирмена')
    story += [heading('1. Исходные данные и выбор модели'),p('Методичка: стр. 53-60; таблица варианта 11 на стр. 58. Наблюдаются 25 фирм. y₁ - доход от юридических услуг, y₂ - доход от реинжиниринга, тыс. ₽. x₁ - число юристов, x₂ - число экономистов, чел. Нулевой y₂ у фирмы 9 сохранён.'),p('Выбрана выходная DEA с переменной отдачей от масштаба (VRS), как в примере презентации преподавателя. Она ищет возможность пропорционально увеличить оба выпуска при прежних ресурсах. Условие Σλ = 1 задаёт выпуклую комбинацию фирм, а не произвольное изменение масштаба.'),heading('2. Линейная математическая модель'),formula([r'\max_{\lambda,\varphi}\ \varphi_i',r'\sum_{j=1}^{25}\lambda_jx_{mj}\leq x_{mi},\quad m=1,2',r'\sum_{j=1}^{25}\lambda_jy_{rj}\geq\varphi_i y_{ri},\quad r=1,2',r'\sum_{j=1}^{25}\lambda_j=1,\quad\lambda_j\geq0,\quad\varphi_i\geq1',r'k_i=1/\varphi_i\in(0,1]']),p('Фирма сама входит в набор эталонов: λᵢ=1, φᵢ=1 допустимы, поэтому φᵢ ≥ 1. kᵢ=1 означает радиальную эффективность относительно этой выборки; kᵢ&lt;1 - резерв пропорционального увеличения доходов. Резерв в процентах равен (φᵢ-1)·100%, а не (1-kᵢ)·100%.'),p('Запись min k с произведением k·Σλy заменена эквивалентной линейной записью через φ = 1/k. В GAMS доходы делятся на 1000 только для улучшения масштаба коэффициентов; оценка эффективности не меняется.','SmallRU'),PageBreak(),heading('3. Данные и эффективность всех 25 фирм'),table(['№','y₁','y₂','x₁','x₂','φ','k','Резерв, %'],[[r['firm'],number(r['y1'],0),number(r['y2'],0),number(r['x1'],0),number(r['x2'],0),number(r['phi'],6),number(r['efficiency'],6),number(r['radial_growth_percent'],2)] for r in rows],[27,58,54,35,35,99,99,W-407],True),Spacer(1,9),p('Единицы: доходы - тыс. ₽; ресурсы - человек. Итоговые k и φ совпали с GAMS до 10⁻⁹. Полная таблица со slack, эталонами, размером и долей юристов: results/lab10_python_dea.csv.','SmallRU'),PageBreak(),heading('4. Интерпретация и эталонные фирмы'),p('Радиально эффективны 14 фирм: '+', '.join(r['firm'] for r in rows if r['radially_efficient']=='True')+'. Во второй фазе отдельно максимизированы нормированные остатки ограничений при фиксированном φ. У всех этих 14 фирм остатки нулевые в пределах допуска: они также сильно эффективны для выбранной VRS-модели.'),p('Для неэффективной фирмы эталон задаётся весами λ. Они могут быть неединственными: совпадение k обязательно, совпадение конкретного набора весов между двумя решателями не требуется. Python выбирает эталон со второй фазой устранения остаточного улучшения; GAMS сохраняет один допустимый радиальный эталон.'),table(['Фирма','k','φ','Эталоны: номер и вес'],[[r['firm'],number(r['efficiency'],6),number(r['phi'],6),r['peers'].replace(';','; ')] for r in rows if r['radially_efficient']!='True'],[45,70,70,W-185],True),heading('5. Проверка оптимальности DEA'),p(f'Для каждой из 25 фирм GAMS/CPLEX: modelstat=1, solvestat=1. Независимо решены прямая и явно построенная двойственная LP в SciPy/HiGHS. Проверены неотрицательность λ, суммы весов, оба ресурса и оба дохода. Максимальная разница k: {v["lab10_max_efficiency_difference"]:.3e}; максимальное нарушение ограничений GAMS-эталонов: {v["lab10_max_gams_peer_violation"]:.3e}.'),formula([r'\min_{v,u,w}\ v^Tx_i+w',r'v^Tx_j-u^Ty_j+w\geq0\ (j=1,\ldots,25),',r'u^Ty_i=1,\quad u,v\geq0,\quad w\in\mathbb{R}']),p('Равенство целевых значений прямой и двойственной задач в пределах допуска подтверждает оптимальность. Сопоставление данных и эталонов выполнено для всех фирм, включая фирму 9 с нулевым доходом второго вида.','SmallRU'),PageBreak(),heading('6. Корреляция Спирмена: размер фирмы'),p('Размер = x₁+x₂. H₀: монотонная связь эффективности с размером отсутствует; H₁: имеется связь любого знака. Двусторонний тест, α=0,05, n=25. При совпадениях используются средние ранги; 14 оценок k=1 образуют одну группу совпадений.'),table(['Показатель','Значение'],[['ρ Спирмена',number(stats[0]['rho'],6)],['t; степени свободы',number(stats[0]['t_stat'],6)+'; 23'],['p, t-аппроксимация',number(stats[0]['p_asymptotic'],6)],['p, перестановочная проверка',number(stats[0]['p_permutation'],6)]],[260,W-260]),p('<b>H₀ не отвергается.</b> По этим данным статистически значимая монотонная связь не выявлена. Это не доказательство отсутствия любой связи и не причинный вывод.'),heading('7. Корреляция Спирмена: доля юристов'),p('Доля юристов = x₁/(x₁+x₂). Гипотезы, уровень значимости и число наблюдений те же.'),table(['Показатель','Значение'],[['ρ Спирмена',number(stats[1]['rho'],6)],['t; степени свободы',number(stats[1]['t_stat'],6)+'; 23'],['p, t-аппроксимация',number(stats[1]['p_asymptotic'],6)],['p, перестановочная проверка',number(stats[1]['p_permutation'],6)]],[260,W-260]),p('<b>H₀ не отвергается.</b> Оценённая корреляция отрицательная, но при α=0,05 недостаточно оснований считать её статистически значимой.'),heading('8. Статистическая проверка и ограничения'),formula([r'\rho_S=\mathrm{corr}(\mathrm{rank}(k),\mathrm{rank}(z)),',r't=\rho_S\sqrt{(n-2)/(1-\rho_S^2)},\quad df=n-2']),p('Для маленькой выборки t-приближение дополнено 200 000 случайными перестановками рангов k (seed=20261007). Двустороннее p рассчитывается по |ρ| с поправкой (счётчик+1)/(B+1). Ошибка Монте-Карло около 0,0011 и 0,0009 соответственно; вывод при 5% устойчив. Перестановочная проверка предполагает обменность наблюдений при нулевой связи. Тест не учитывает возможную зависимость оценок DEA из-за общей оценённой границы; результаты интерпретируются как учебный анализ данной выборки.','SmallRU'),PageBreak(),heading('9. Сопоставление эффективности')]
    fig,ax=plt.subplots(figsize=(8,4));vals=[float(r['efficiency']) for r in rows];ax.bar(range(1,26),vals,color=['#216e94' if z<1-1e-8 else '#39a080' for z in vals]);ax.set_xticks(range(1,26));ax.set_xlabel('Фирма');ax.set_ylabel('k = 1 / φ');ax.set_ylim(.75,1.03);ax.axhline(1,color='#697b89',lw=1);fig.tight_layout();path=TEMP/'dea_efficiency.png';fig.savefig(path,dpi=145);plt.close(fig)
    story += [Image(str(path),width=W,height=W/2),p('Зелёным показаны эффективные фирмы. Шкала вертикальной оси начинается с 0,75, чтобы различия были видны; она не отражает абсолютную доходность бизнеса.','SmallRU'),heading('10. Реализация и источники'),p('Исходник models/lab10.gms решает 25 LP в цикле. Данные - data/dea-variant-11.csv и models/dea-data.inc. GAMS-результаты - lab10_gams_dea.csv и lab10_gams_peers.csv. Независимые проверки и статистика - independent_check.py; исходные значения тестов - lab10_stats.json. Полный протокол - logs/lab10.lst.','SmallRU')]+code("inputs(m).. sum(j,x(j,m)*intensity(j)) =l= xref(m);\noutputs(r).. sum(j,y(j,r)*intensity(j)) =g= phi*yref(r);\nconvexity.. sum(j,intensity(j)) =e= 1;\nsolve dea using lp maximizing phi;\nreport(i,'k')=1/phi.l;")
    story += [Spacer(1,10),ref('Карточка №10: пункты 1-3','https://sdo.timacad.ru/mod/assign/view.php?id=42828'),ref('Лекция преподавателя: анализ эффективности бизнеса','http://svetlov.timacad.ru/umk7/lekmmub7.ppt'),ref('Официальная модель DEA в библиотеке GAMS: структура LP и VRS/CRS','https://www.gams.com/latest/gamslib_ml/libhtml/gamslib_dea.html'),ref('SciPy: корреляция Спирмена и замечание о маленьких выборках','https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.spearmanr.html'),p('Библиотечная DEA-модель использована как справочный пример структуры. Её ориентация на ресурсы не скопирована: основной расчёт здесь имеет выходную ориентацию и VRS. Готовое решение чужого индивидуального варианта не использовано.','SmallRU')]
    return build('lab10_variant11_report.pdf',story)

